function header(){return `<a class="skip" href="#main">${t('본문으로 이동','Skip to content')}</a><header class="header"><div class="wrap header-inner"><a class="brand" href="${url('home')}" aria-label="EASI Lab · Dong Hun Lee ${t('홈','home')}"><span class="brand-name">EASI<span class="brand-dot">.</span></span><span class="brand-divider"></span><span class="brand-identity"><span>DONG HUN LEE LAB</span><small>SEOUL NATIONAL UNIVERSITY</small></span><span class="brand-fullname">${labFullName}</span></a><nav class="nav" aria-label="${t('주 메뉴','Main navigation')}">${['pi','research','stories','publications','members','join','collaborate'].map(k=>`<a href="${url(k)}" ${(page===k||(page.startsWith('story-')&&k==='stories'))?'aria-current="page"':''} class="${k==='collaborate'?'nav-cta':''}">${t(...names[k])}${k==='collaborate'?'<span aria-hidden="true">↗</span>':''}</a>`).join('')}</nav><div class="lang" aria-label="${t('언어 선택','Language selection')}"><a href="${languageHref('ko')}" data-lang="ko" lang="ko" hreflang="ko" class="${lang==='ko'?'active':''}" ${lang==='ko'?'aria-current="true"':''} aria-label="한국어">KR</a><span aria-hidden="true">/</span><a href="${languageHref('en')}" data-lang="en" lang="en" hreflang="en" class="${lang==='en'?'active':''}" ${lang==='en'?'aria-current="true"':''} aria-label="English">EN</a></div><button type="button" class="menu-toggle" aria-expanded="false" aria-controls="mobile-menu" aria-label="${t('메뉴 열기','Open menu')}"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true"><path d="M3 8h18M3 16h18"/></svg></button></div><nav class="mobile-nav" id="mobile-menu" aria-label="${t('모바일 메뉴','Mobile navigation')}">${['pi','home','research','stories','methods','publications','members','join','news','funding','collaborate'].map(k=>`<a href="${url(k)}" ${(page===k||(page.startsWith('story-')&&k==='stories'))?'aria-current="page"':''} class="${k==='collaborate'?'nav-cta':''}">${t(...names[k])}${k==='collaborate'?'<span aria-hidden="true">↗</span>':''}</a>`).join('')}</nav></header>`}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-top"><div class="footer-brand"><div class="footer-title">EASI<span class="brand-dot">.</span></div><div><div class="footer-fullname">Epigenetics, Aging & Skin Inflammation</div><p>Dong Hun Lee Lab · Seoul National University<br>${t('서울대학교 의과대학 · 서울대학교병원 피부과','Department of Dermatology, SNU College of Medicine & SNUH')}<br>Seoul, Republic of Korea</p></div></div><div class="footer-links"><a href="${url('members')}">${t('구성원','Members')}</a><a href="${url('collaborate')}">${t('공동연구','Collaborate')}</a><a href="${url('methods')}">Methods & Expertise</a><a href="${url('news')}">${t('소식','News')}</a><a href="${url('join')}">${t('연구 참여','Join the lab')}</a><a href="${url('funding')}">${t('연구지원','Funding')}</a><button type="button" class="contact-link" data-contact-email>${t('이메일','Email')} ↗</button></div></div><div class="footer-connections"><div><span class="eyebrow">Profiles</span>${profileLinks()}</div><div><span class="eyebrow">${t('관련 기관','Institutions')}</span><div class="institution-links">${institutions.map(i=>external(connections[i.key],t(i.ko,i.en)+' '+arrow)).join('')}</div></div></div><div class="footer-bottom"><span>© 2026 Dong Hun Lee Lab · EASI Lab</span><span><a href="${url('about')}">${t('자료 출처 및 개인정보 안내','Sources & privacy')}</a><a href="${url('about')}#email-policy">${t('이메일 무단수집 거부','No email harvesting')}</a></span></div></div></footer>`}
function pageHead(kicker,title,desc){return `<div class="wrap page-head"><div class="eyebrow accent">${kicker}</div><h1>${title}</h1><p class="lead">${desc}</p></div>`}
function joinBand(){return `<section class="join-band"><div class="wrap join-inner"><div><div class="eyebrow"><span class="status-dot"></span> Students · Researchers · Industry partners</div><h2>${t('함께 풀고 싶은<br>질문이 있나요?','A question we could<br>answer together?')}</h2><p>${t('피부노화·후성유전체, 염증성 피부질환, 피부–뇌 연결, 의료기기·EBD.<br>연구 아이디어 단계부터 편하게 연락해 주세요.','Skin aging and epigenomics, inflammatory skin disease, skin–brain interaction, medical devices and EBD. Get in touch—even at the earliest idea stage.')}</p></div><div class="join-aside"><div class="join-monogram" aria-hidden="true">EASI<span class="brand-dot">.</span></div><p>${t('대학원생·학부 인턴의 연구 참여와 교내외 연구자·의료진·산업체의 공동연구 제안을 환영합니다.','We welcome prospective students and interns, and collaboration proposals from researchers, clinicians and industry partners.')}</p><div class="actions"><a class="button light" href="${url('collaborate')}">${t('공동연구 제안','Propose a collaboration')} ${arrow}</a><a class="text-link" href="${url('join')}">${t('학생 연구 참여','Student opportunities')} ${right}</a></div></div></div></section>`}
function paperCard(id){if(!isLeadPaper(id))return '';const p=pick(id),h=highlights[id];return `<article class="paper-card"><div class="paper-art ${h.image?'paper-data':''}"><img src="${basePath}/assets/${h.image||artFiles[h.art==='immune'?'immunity':h.art]}" alt="" loading="lazy" width="600" height="330">${h.image?'':`<span class="paper-art-label">${h.word}</span>`}</div><div class="paper-body"><div class="paper-meta">${p.year} · ${t(...h.label)}</div><h3>${external(p.url,t(...h.title))}</h3><p>${t(...h.desc)}</p>${collaborationCredit(id)}<div class="paper-foot"><span>${h.journal}</span>${external(p.url,arrow)}</div></div></article>`}
const newsItems=[
{date:'2026.07',type:['연구 논문','Publication'],title:['아토피피부염의 OX40+ 조절 T세포 연구','Investigating OX40+ regulatory T cells in atopic dermatitis'],desc:['고차원 면역분석 연구가 Allergology International에 게재되었습니다.','High-dimensional immune profiling research published in Allergology International.'],url:'https://doi.org/10.1016/j.alit.2026.02.004'},
{date:'2026.02',type:['연구 논문','Publication'],title:['miR-382-5p와 진피 노화의 분자 기전','miR-382-5p and the molecular mechanisms of dermal aging'],desc:['miR-382-5p–SLC26A3 연구가 Experimental Dermatology에 게재되었습니다.','Research on the miR-382-5p–SLC26A3 axis published in Experimental Dermatology.'],url:'https://doi.org/10.1111/exd.70218'},
{date:'2026.01',type:['학술 활동','Academic leadership'],title:['이동훈 교수, Experimental Dermatology 편집장 취임','Dong Hun Lee appointed Editor-in-Chief of Experimental Dermatology'],desc:['2026년 1월부터 Editor-in-Chief로 활동합니다.','Serving as Editor-in-Chief from January 2026.'],url:'https://doi.org/10.1111/exd.70230'},
{date:'2025.08',type:['연구 논문','Publication'],title:['말초 substance P와 기억·시냅스 가소성 연구','Peripheral substance P, memory and synaptic plasticity'],desc:['동물모델 연구가 Molecular Brain에 게재되었습니다.','An animal-model study published in Molecular Brain.'],url:'https://doi.org/10.1186/s13041-025-01242-6'}];
function newsRows(n=4){return `<div class="news-list">${newsItems.slice(0,n).map(x=>`<article class="news-row"><time class="news-date" datetime="${x.date.replace('.','-')}">${x.date}</time><div><div class="news-type">${t(...x.type)}</div><h3>${external(x.url,t(...x.title))}</h3><p>${t(...x.desc)}</p>${collaborationCredit(paperIdForUrl(x.url))}</div>${external(x.url,arrow)}</article>`).join('')}</div>`}
const researchSlides=window.LAB_RESEARCH_SLIDES;
function researchCarousel(){return `<section class="hero-figure research-carousel" data-carousel role="region" aria-roledescription="${t('슬라이드 쇼','carousel')}" aria-label="${t('논문 속 연구 이미지','Images from our research')}"><div class="experiment-topline"><span>FROM OUR RESEARCH</span><span data-slide-count>01 / ${String(researchSlides.length).padStart(2,'0')}</span></div><div class="experiment-stage" data-slide-stage aria-live="off">${researchSlides.map((s,i)=>`<figure class="experiment-slide ${i===0?'is-active':''}" data-slide role="group" aria-roledescription="${t('슬라이드','slide')}" aria-label="${i+1} / ${researchSlides.length}" aria-hidden="${i!==0}" ${i!==0?'inert':''}><a class="experiment-image" href="${basePath}/assets/${s.file}" target="_blank" rel="noopener noreferrer" aria-label="${E(t('연구 이미지 크게 보기: ','View full-size research image: ')+t(...s.title))}"><img src="${basePath}/assets/${s.file}" width="${s.width}" height="${s.height}" ${i===0?'fetchpriority="high"':'loading="eager"'} decoding="async" alt="${E(t(...s.alt))}"></a><figcaption class="experiment-caption"><div class="experiment-topic">${E(s.topic)}</div><h2>${t(...s.title)}</h2><p>${t(...s.caption)}</p>${s.methods?`<ul class="experiment-methods" aria-label="${t('논문에서 사용한 연구 방법','Methods used in this study')}">${s.methods.map(m=>`<li>${E(m)}</li>`).join('')}</ul>`:''}${collaborationCredit(paperIdForUrl(s.doi))}<div class="experiment-source">${external(s.doi,`${E(s.shortCitation)} · ${E(s.panel)} ↗`)}<span>${t('논문 그림 발췌','Figure excerpt')} · ${external(s.licenseUrl,s.license)}</span></div></figcaption></figure>`).join('')}</div><div class="experiment-controls"><button type="button" data-autoplay data-pause-label="${t('이미지 자동 전환 일시정지','Pause automatic image rotation')}" data-play-label="${t('이미지 자동 전환 시작','Start automatic image rotation')}" data-pause-text="${t('일시정지','Pause')}" data-play-text="${t('자동 재생','Play')}" aria-label="${t('이미지 자동 전환 일시정지','Pause automatic image rotation')}"><span data-play-icon aria-hidden="true">Ⅱ</span><span data-play-label>${t('일시정지','Pause')}</span></button><div class="experiment-dots" role="group" aria-label="${t('연구 이미지 선택','Choose research image')}">${researchSlides.map((s,i)=>`<button type="button" data-slide-to="${i}" aria-pressed="${i===0}" aria-label="${E((i+1)+'. '+t(...s.title))}"></button>`).join('')}</div><div class="experiment-arrows"><button type="button" data-slide-step="-1" aria-label="${t('이전 이미지','Previous image')}">←</button><button type="button" data-slide-step="1" aria-label="${t('다음 이미지','Next image')}">→</button></div></div></section>`}
function researchImageCredits(){return `<div class="figure-credits">${researchSlides.map(s=>`<div class="figure-credit"><strong>${external(s.doi,E(s.citation))}</strong><small>${E(s.panel)} · ${external(s.licenseUrl,E(s.rightsFull||s.license))} · ${t('원본 논문의 해당 패널을 발췌했습니다. 색상·대비·실험 데이터는 변경하지 않았습니다.','Selected panels cropped from the original paper. Colors, contrast and experimental data are unchanged.')}</small>${collaborationCredit(paperIdForUrl(s.doi))}</div>`).join('')}</div>`}
function researchApproach(){return `<section class="section approach-section" id="approach"><div class="wrap"><div class="section-head"><div><div class="eyebrow accent">Questions drive the methods</div><h2>${t('복잡한 질문을,<br>여러 층위의 근거로.','Complex questions.<br>Connected approaches.')}</h2></div><p class="approach-intro">${t('환자에서 발견한 현상을 세포 지도와 데이터 분석으로 해석하고, 기전 가설을 기능 실험으로 검증합니다.','We connect patient observations with cellular maps and computational analysis, then test mechanistic hypotheses through functional experiments.')}</p></div><div class="approach-grid">${[
 ['01','질환의 다양성을 포착하다','Map the heterogeneity','임상 표현형과 PBMC single-cell RNA-seq를 연결하고, flow cytometry와 공개 피부 데이터로 관찰을 교차 확인합니다.','Connect clinical phenotypes with PBMC single-cell RNA-seq, and cross-check observations using flow cytometry and public skin datasets.','Clinical phenotyping · Single-cell · Flow cytometry',178],
 ['02','데이터에서 가설을 좁히다','Make the hypotheses specific','세포 상태·조절 네트워크·상호작용을 추론하고, 여러 조건의 transcriptome을 통합해 검증할 후보를 선정합니다.','Infer cell states, regulatory programs and potential interactions; integrate transcriptomes across conditions to prioritize candidates.','Pseudotime · Regulatory networks · Transcriptomics',149],
 ['03','기전을 실험으로 검증하다','Put mechanisms to the test','유전자 조절과 수용체 길항 실험을 세포 기능, 동물 행동 및 전기생리 평가와 연결해 기전 가설을 시험합니다.','Test mechanistic hypotheses through gene perturbation and receptor antagonism, connected to cellular, behavioral and electrophysiological readouts.','Gene perturbation · Pharmacology · Functional readouts',179]
].map(x=>`<article class="approach-card"><div class="approach-number">${x[0]}</div><h3>${t(x[1],x[2])}</h3><p>${t(x[3],x[4])}</p><div class="approach-techniques">${x[5]}</div>${external(pick(x[6]).url,t('관련 연구 보기','Explore the study')+' '+arrow,'text-link')}${collaborationCredit(x[6])}</article>`).join('')}</div></div></section>`}
function home(){return `<main id="main"><section class="hero wrap"><div class="hero-topline"><p class="hero-lab-title">${labFullName}</p><span class="hero-location">SEOUL, KOREA <span aria-hidden="true">↗</span></span></div><div class="hero-grid"><div class="hero-copy"><div class="hero-kicker"><span></span>${t('서울대학교 이동훈 교수 연구실','Dong Hun Lee Lab · Seoul National University')}</div><h1>${t('피부의 시간,<br><em>그 너머의 연결.</em>','How skin ages.<br><em>How skin<br>connects.</em>')}</h1><p class="hero-desc">${t('임상에서 마주한 복잡한 질문을 single-cell·bioinformatics·기능 실험으로 연결해 피부와 전신의 기전을 탐구합니다.','We connect clinical questions, single-cell analysis and bioinformatics with functional experiments to understand skin aging, inflammation and skin–brain interaction.')}</p><div class="hero-methods" aria-label="${t('연구 접근','Research approaches')}"><span>Single-cell</span><span>Bioinformatics</span><span>Functional studies</span></div><div class="actions"><a class="button" href="${url('research')}">${t('연구 살펴보기','Explore our research')} ${arrow}</a><a class="text-link" href="${url('join')}">${t('연구실 함께하기','Join the lab')} ${right}</a></div><div class="hero-signature"><span class="signature-line"></span><span>Dong Hun Lee, MD, PhD, MBA<br><small>${t('서울대학교 의과대학 피부과학교실 교수','Professor of Dermatology · SNU College of Medicine')}</small></span></div></div>${researchCarousel()}</div><div class="research-index" aria-label="${t('네 연구 분야','Four research directions')}">${areas.map((a,i)=>`<a href="${url('research')}#${a.key}" class="research-index-item"><span class="index-number">0${i+1}</span><span><strong>${a.en}</strong><small>${t(a.ko,['Gene regulation & time','Peripheral signals & brain function','Inflammation & clinical phenotypes','Energy, imaging & translation'][i])}</small></span>${arrow}</a>`).join('')}</div></section>${affiliationRibbon()}${researchApproach()}${discoveryLinks()}<section class="section wrap research-editorial"><div class="intro"><div><div class="eyebrow accent">Our scientific perspective</div><p class="intro-side">${t('생물학에서 의료기기까지.<br>하나의 출발점, 피부.','From biology to medical devices.<br>One starting point: skin.')}</p></div><p>${t('시간과 환경이 피부를 어떻게 바꾸는지,<br>피부의 신호가 뇌와 어떻게 연결되는지,<br>염증은 질환으로 어떻게 이어지는지 묻습니다.<br>이 질문들을 의료기기와 정밀한 평가 기술로 확장합니다.','How do time and environment change the skin? How do skin-derived signals connect to the brain? How does inflammation become disease? These questions also guide our work in medical devices and precise outcome assessment.')}</p></div><div class="areas">${areas.map((a,i)=>`<article class="area" data-area="${a.key}"><a class="area-art" href="${url('research')}#${a.key}" aria-label="${t(a.ko,a.en)}"><img src="${basePath}/assets/${artFiles[a.key]}" width="720" height="480" alt="" loading="lazy"><span>0${i+1} / ${['TIME','CONNECTION','DISEASE','TECHNOLOGY'][i]}</span>${arrow}</a><div class="area-head"><span class="area-num">0${i+1}</span><span class="area-icon">${icons[a.key]}</span></div><div class="enlabel">${a.en}</div><h3>${t(a.ko,a.en)}</h3><p>${t(...a.desc)}</p><a class="text-link" href="${url('research')}#${a.key}">${t('연구 질문과 논문','Questions & publications')} ${right}</a></article>`).join('')}</div></section><section class="section tinted discoveries"><div class="wrap"><div class="section-head"><div><div class="eyebrow accent">Selected research</div><h2>${t('질문에서 발견으로.','From questions to discoveries.')}</h2></div><a class="text-link" href="${url('publications')}">${t('논문 전체 보기','All publications')} ${arrow}</a></div>${selectionPolicy()}<div class="paper-grid">${[208,149,179].map(paperCard).join('')}</div><p class="feature-source">${t('각 연구 제목에서 원문을 확인할 수 있습니다. 동물연구 결과는 사람에서의 임상 효과를 의미하지 않습니다.','Article titles link to the original publications. Animal-model findings do not establish clinical effects in humans.')}</p></div></section><section class="section wrap pi-preview"><div class="pi-preview-heading"><a class="pi-preview-portrait" href="${url('pi')}" aria-label="${t('이동훈 교수 소개','About Dong Hun Lee')}"><img src="${basePath}/assets/dong-hun-lee-2025.jpg" width="1734" height="2048" alt="${t('이동훈 교수, 2025년','Dong Hun Lee, 2025')}" loading="lazy"></a><div class="eyebrow accent">Principal investigator</div><h2>${t('이동훈 교수','Dong Hun Lee')}<span>MD, PhD, MBA</span></h2><p>${t('피부과 의사과학자.<br>임상에서 시작해 기전으로 이어지는 연구.','Physician-scientist.<br>Connecting clinical questions with biological mechanisms.')}</p><div class="actions"><a class="text-link" href="${url('pi')}">${t('연구책임자 소개','Meet our principal investigator')} ${arrow}</a><a class="text-link" href="${url('members')}">${t('연구실 구성원','Meet the team')} ${right}</a></div>${profileLinks()}</div><div class="pi-preview-roles"><div><time>2026.01 —</time><h3>${external(connections.mrc,t('서울대학교 의학연구원 부원장','Vice President, Medical Research Center')+' '+arrow)}</h3><p>Seoul National University</p></div><div><time>2026.06 —</time><h3>${external(connections.translational,t('서울대학교병원 중개의학연구소 소장','Director, Translational Medicine Research Institute')+' '+arrow)}</h3><p>${t('서울대학교병원 의생명연구원','Biomedical Research Institute, Seoul National University Hospital')}</p></div><div><time>2026.01 —</time><h3>${external(connections.experimentalDermatology,'Editor-in-Chief (EIC) '+arrow)}</h3><p>Experimental Dermatology</p></div></div></section><section class="section wrap news-section"><div class="section-head"><div><div class="eyebrow accent">News & milestones</div><h2>${t('연구실의 기록.','Notes from the lab.')}</h2></div><a class="text-link" href="${url('news')}">${t('소식 더 보기','All updates')} ${arrow}</a></div>${newsRows(3)}</section>${joinBand()}</main>`}
function researchActions(area){
 const project={aging:'aging',neuro:'skin-brain',immunity:'inflammation',devices:'devices'}[area.key];
 return `<div class="actions research-actions" data-research-actions="${area.key}"><a class="text-link" href="${E(topicInquiry(project))}">${t('공동연구 제안','Discuss a collaboration')} ${arrow}</a><a class="text-link" href="${E(url('publications','&topic='+area.key))}">${t('관련 논문 더 보기','More related publications')} ${right}</a></div>`;
}
function research(){return `<main id="main">${pageHead('Research',t('피부에서 시작하는<br>더 넓은 생물학.','Skin biology.<br>A wider perspective.'),t('노화의 분자 기전, 피부–뇌 신호, 염증의 면역 지형에서 의료기기·EBD까지. 피부에서 시작한 질문을 기전·기술·평가로 연결합니다.','Our work connects epigenetic skin aging, skin–brain interaction and inflammatory skin disease with medical devices, energy-based technologies and objective assessment.'))}<div class="wrap">${areas.map((a,i)=>`<section id="${a.key}" class="research-block"><div><div class="index">0${i+1}</div><h2>${t(a.ko,a.en)}</h2><div class="enlabel">${a.en}</div><figure class="research-illustration"><img src="${basePath}/assets/${artFiles[a.key]}" width="720" height="480" alt="${t(a.ko+'을 표현한 개념 일러스트레이션','Conceptual illustration: '+a.en)}" loading="lazy"><figcaption>${t('연구 주제 개념도','Research theme illustration')}</figcaption></figure></div><div class="research-content"><h3>${t(...a.question)}</h3><p>${t(...a.body)}</p>${a.key==='devices'?`<aside class="device-background"><h4>${E(t(...content.deviceResearch.background.title))}</h4><p>${E(t(...content.deviceResearch.background.description))}</p><a class="text-link" href="${url('pi')}">${t('연구책임자 소개','Meet the principal investigator')} ${right}</a></aside>`:''}<div class="tag-row">${a.tags.map(x=>`<span class="tag">${x}</span>`).join('')}</div>${relatedResearch(a)}${researchActions(a)}${a.key==='devices'?`<p class="article-note">${external(t('https://snumrc.snu.ac.kr/iheib/about/research-areas','https://snumrc.snu.ac.kr/iheib/en/about/research-areas'),t('소속 IHEIB의 연구 분야','Research areas at IHEIB')+' '+arrow)}</p>`:''}${a.key==='neuro'?`<p class="article-note">${t('이 연구 축의 대표 기전 연구는 동물모델 기반입니다.','The highlighted mechanistic studies in this direction use animal models.')}</p>`:''}</div></section>`).join('')}</div>${researchApproach()}${discoveryLinks()}${joinBand()}</main>`}
function filteredPapers(f){return publications.filter(p=>(f.scope!=='selected'||(p.selected&&isLeadPaper(p.id)))&&(f.year==='all'||String(p.year)===f.year)&&(f.topic==='all'||p.topic===f.topic||(f.topic==='devices'&&devicePaperIds.has(p.id)))&&(!f.search||(p.title+' '+p.authors+' '+p.citation).toLowerCase().includes(f.search.toLowerCase().trim()))).sort((a,b)=>b.year-a.year||b.id-a.id)}
function pubRows(){const all=filteredPapers(filters);const max=Math.max(1,Math.ceil(all.length/12));filters.page=Math.min(filters.page,max);const list=all.slice((filters.page-1)*12,filters.page*12);return `<div class="pub-summary"><span role="status" aria-live="polite">${t(`${all.length}개 항목`,`${all.length} publications`)}</span><span>${t('연도 내 정렬: CV 역순','Within each year: reverse CV order')}</span></div><div class="pub-list">${list.length?list.map(p=>`<article class="pub-row"><div class="pub-year">${p.year}</div><div><h3>${external(p.url,E(p.title))}</h3><p class="authors">${E(p.authors).replace(/Lee DH\*?/g,'<strong>$&</strong>')}</p><p class="journal">${E(p.journal.split(/doi:|PMID:/i)[0])}</p>${collaborationCredit(p.id)}<details><summary>${t('전체 서지정보','Full citation')}</summary><p>${E(p.citation)}</p></details></div><div class="pub-links">${external(p.url,`${p.doi?'DOI':p.pmid?'PubMed':t('검색','Search')} ↗`)}${p.pmid&&p.doi?external(`https://pubmed.ncbi.nlm.nih.gov/${p.pmid}/`,'PubMed ↗'):''}</div></article>`).join(''):`<div class="empty"><h3>${t('검색 결과가 없습니다.','No matching publications.')}</h3><p class="muted small">${t('검색어를 바꾸거나 필터를 초기화해 주세요.','Try a different term or reset the filters.')}</p><button class="button outline" style="margin-top:20px" data-reset>${t('필터 초기화','Reset filters')}</button></div>`}</div><div class="pagination"><button type="button" data-pagination="-1" ${filters.page===1?'disabled':''}>← ${t('이전','Previous')}</button><span>${filters.page} / ${max}</span><button type="button" data-pagination="1" ${filters.page===max?'disabled':''}>${t('다음','Next')} →</button></div>`}
function publicationsPage(){return `<main id="main">${pageHead('Publications',t('질문을 발견으로,<br>발견을 지식으로.','From questions<br>to shared knowledge.'),t('주요 연구와 전체 서지 목록을 탐색하세요. 연구 주제, 발행 연도, 제목·저자 검색으로 관심 논문을 찾을 수 있습니다.','Explore selected work and our bibliography. Find papers by research direction, publication year, title or author.'))}<section class="section wrap" style="padding-top:35px"><div class="pub-controls"><div class="filter-field"><label for="pub-search">${t('제목·저자·키워드','Title, author or keyword')}</label><input type="search" id="pub-search" value="${E(filters.search)}" placeholder="${t('예: epigenetics, atopic, dopamine','Try epigenetics, atopic, dopamine')}" autocomplete="off"></div><div class="filter-field"><label for="pub-year">${t('발행 연도','Publication year')}</label><select id="pub-year"><option value="all">${t('전체 연도','All years')}</option>${[...new Set(publications.map(p=>p.year))].sort((a,b)=>b-a).map(y=>`<option value="${y}" ${filters.year===String(y)?'selected':''}>${y}</option>`).join('')}</select></div><div class="filter-field"><label for="pub-scope">${t('논문 범위','Collection')}</label><select id="pub-scope"><option value="all" ${filters.scope==='all'?'selected':''}>${t('전체 목록','All publications')}</option><option value="selected" ${filters.scope==='selected'?'selected':''}>${t('대표 논문 · 주저자','Selected · lead author')}</option></select></div></div><div class="chips" aria-label="${t('주제 필터','Topic filters')}">${[['all','전체','All'],['aging','후성유전학적 피부노화','Epigenetic skin aging'],['neuro','피부–뇌 상호작용','Skin–brain interaction'],['immunity','염증성 피부질환','Inflammatory skin disease'],['devices','의료기기·EBD·피부영상','Medical devices / EBD / imaging'],['other','기타 연구','Other work']].map(x=>`<button type="button" class="chip ${filters.topic===x[0]?'active':''}" aria-pressed="${filters.topic===x[0]}" data-topic="${x[0]}">${t(x[1],x[2])}</button>`).join('')}</div>${selectionPolicy()}<div id="pub-results">${pubRows()}</div><div class="note">${t('첨부 CV의 “발표 논문” 섹션 215개 항목을 수록했습니다. 원저·리뷰·Letter·Editorial이 함께 포함되어 있습니다. 주제 분류는 탐색을 돕기 위한 분류이며, 원문의 서지정보와 구분됩니다.','This bibliography contains 215 entries from the supplied CV’s publication section, including original articles, reviews, letters and editorials. Topic labels are navigation aids, separate from the original bibliographic metadata.')}</div></section></main>`}
